 function renderHomePriority(){if(renderEmptyHome())return;const started=startedVideos().filter(row=>!row.progress.completed&&row.progress.percent<98),resume=$('#priorityResumeCard');if(resume)resume.hidden=!started.length;const fallback=managedVideoDetails(HOME_VIDEOS_DATA[0]),entry=started[0]||{video:fallback,progress:progressForVideo(fallback.id)},video=entry.video,progress=entry.progress,pct=Math.max(0,Math.min(100,Math.round(progress.percent||0))),hasHistory=progress.time>0,routePath='/video/'+video.id;const card=$('#priorityResumeCard'),primary=$('#todayPrimaryAction');if(card)card.dataset.route=routePath;if(primary){primary.dataset.route=routePath;primary.textContent=hasHistory?'继续学习':'开始第一课'}const cover=$('#priorityResumeCover');if(cover){cover.src=video.cover||'assets/images/home_video_1.png';cover.alt=displayVideoTitle(video)}if($('#priorityResumeLabel'))$('#priorityResumeLabel').textContent=hasHistory?'继续上次学习':'开始你的第一个 Vlog';if($('#priorityResumeTitle'))$('#priorityResumeTitle').textContent=displayVideoTitle(video);if($('#priorityResumeProgress'))$('#priorityResumeProgress').textContent=hasHistory?`播放到 ${pct}%`:'尚未开始';if($('#priorityResumeTime'))$('#priorityResumeTime').textContent=hasHistory?`从 ${fmt(progress.time)} 继续`:`${fmt(video.duration)} · ${difficultyLabel(video.level)}`;if($('#priorityResumeBar'))$('#priorityResumeBar').style.width=pct+'%';const launcher=$('.progress-launcher');if(launcher)launcher.dataset.route=routePath}
