 function syncHomeDiscoveryHeading(){const continuing=startedVideos().length>0&&State.homeCategory==='热门';if($('#continueTitle'))$('#continueTitle').textContent=State.lang==='en'?(continuing?'Continue Learning':'Recommended for You'):(continuing?'继续学习':'为你推荐');if($('#continueDesc'))$('#continueDesc').textContent=State.lang==='en'?(continuing?'Pick up from your real last position':'Chosen by level, topic, and length'):(continuing?'从本人实际观看位置接着学':'按难度、主题和时长选择')}
 function bindHomeCategoryButtons(){ $$('#homeCategoryRow button').forEach(btn=>btn.onclick=()=>{State.homeTag=null;State.homeCategory=btn.dataset.cat;renderHomeCategoryState();renderHomeHomeSections();toast('已切换到「'+State.homeCategory+'」内容');logEvent('home.category',State.homeCategory);renderLogic()}) }
function renderHomeHomeSections(){const all=window.EastudyCatalog?.publishedVideos(HOME_VIDEOS_DATA.map(managedVideoDetails))||[],filtered=State.homeTag?(window.EastudyCatalog?.queryVideos(all,{tagId:State.homeTag})||[]):itemsForCategory(all,State.homeCategory,all.length),recommended=filtered.slice(0,4).sort((a,b)=>progressForVideo(a.id).time-progressForVideo(b.id).time),started=startedVideos().slice(0,4),videoRows=!State.homeTag&&started.length&&State.homeCategory==='热门'?started.map(x=>x.video):recommended;syncHomeDiscoveryHeading();$('#videoCards').innerHTML=videoRows.length?videoRows.map(v=>videoCardMarkup(v,{showProgress:true})).join(''):`<div class="home-inline-empty"><b>暂时没有符合条件的视频</b><span>当前筛选没有已发布内容。</span><button type="button" id="clearHomeFilter">查看全部内容</button></div>`;$('#clearHomeFilter')?.addEventListener('click',()=>{State.homeCategory='热门';State.homeTag=null;renderHomeCategoryState();renderHomeHomeSections();renderHotTags()});const collections=State.homeTag?[]:itemsForCategory(HOME_COLLECTIONS_DATA,State.homeCategory,5).filter(c=>c.count>0);$('#collectionCards').innerHTML=collections.length?collections.map(c=>`<article class="home-collection-card" data-route="/compilation/${c.id}" data-category="${c.category}" tabindex="0"><div class="collection-img"><img src="${c.cover}" alt="${c.title}"></div><div class="collection-info"><b>${c.title}</b><span>${c.count} 个视频</span></div></article>`).join(''):`<div class="home-inline-empty"><b>当前筛选暂无合集</b><span>你可以先从上方真实视频开始。</span></div>`;const latest=all.filter(v=>v.publishedAt).sort((a,b)=>Date.parse(b.publishedAt)-Date.parse(a.publishedAt));$('#homeLatestCards').innerHTML=latest.slice(0,4).map(v=>videoCardMarkup(v)).join('');const dailyVideo=recommended[0]||(!State.homeTag?all[0]:null),dailyBox=$('.daily-pick');if(dailyBox)dailyBox.hidden=!dailyVideo;const dailyImg=document.querySelector('.daily-thumb img');if(dailyImg&&dailyVideo){dailyImg.src=dailyVideo.cover;dailyImg.alt=displayVideoTitle(dailyVideo)}const dailyH=$('.daily-pick h4'),dailyP=$('.daily-pick p');if(dailyH&&dailyVideo)dailyH.textContent=displayVideoTitle(dailyVideo);if(dailyP&&dailyVideo)dailyP.textContent=`${fmt(dailyVideo.duration||0)} · ${difficultyLabel(dailyVideo.level)}`;document.querySelectorAll('.daily-pick [data-route]').forEach(btn=>{if(dailyVideo)btn.dataset.route='/video/'+dailyVideo.id});renderHomeGoal();renderHomePriority();bindCards();}

