async function savePersonalToggle(key,on,button,render,message){
 if(button.disabled)return;
 const userId=currentStudentStorageId(),sourceRoute=State.route;
 button.disabled=true;
 try{
  const result=await window.EastudyPersonalLibrary.saveToggle({key,active:on,getUserId:currentStudentStorageId,data:window.EastudyData,cache:Storage});
  if(currentStudentStorageId()!==userId||State.route!==sourceRoute||!button.isConnected)return;
  if(result.error){if(result.error.code!=='SAVE_PENDING')toast('未能保存，请检查网络后重试');return}
  render();toast(message);
 }finally{if(currentStudentStorageId()===userId&&State.route===sourceRoute&&button.isConnected)button.disabled=false}
}
