const LEARNING_TRACKS=[
 {id:'general',group:'口语能力',name:'Vlog 综合口语',level:'综合',focus:'通过真实生活视频练习听力与表达'},
 {id:'daily',group:'口语能力',name:'日常口语',level:'生活',focus:'听懂生活场景中的自然英语'},
 {id:'cet4',group:'学习目标',name:'四级',level:'CET-4',focus:'积累常见话题词汇与基础听力'},
 {id:'cet6',group:'学习目标',name:'六级',level:'CET-6',focus:'适应自然语速和更复杂的表达'},
 {id:'ielts',group:'学习目标',name:'雅思',level:'IELTS',focus:'拓展生活话题与观点表达'},
 {id:'toefl',group:'学习目标',name:'托福',level:'TOEFL',focus:'练习信息理解与清晰表达'},
 {id:'tem8',group:'学习目标',name:'专八',level:'TEM-8',focus:'挑战更丰富的词汇和自然语流'}
];
function currentLearningPlan(){const saved=Storage.get('learningPlan',{})||{},daily=[10,20,40,60].includes(Number(saved.dailyMinutes))?Number(saved.dailyMinutes):20,aliases={ielts_academic:'ielts',ielts_general:'ielts'},candidate=aliases[saved.track]||saved.track,track=LEARNING_TRACKS.some(x=>x.id===candidate)?candidate:'general';return {track,dailyMinutes:daily,selfLevel:saved.selfLevel||'unsure',timezone:saved.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Shanghai',onboardingVersion:Number(saved.onboardingVersion)||0,revision:Number(saved.revision)||0}}
function learningTrack(id=currentLearningPlan().track){return LEARNING_TRACKS.find(x=>x.id===id)||LEARNING_TRACKS[0]}
function queueSourceVideos(){const managed=window.ZoContent?.listVideos?.({publishedOnly:true})||[];return (managed.length?managed:HOME_VIDEOS_DATA.map(managedVideoDetails)).map(video=>({...video,mediaUrl:video.mediaUrl||managedVideoDetails(video).mediaUrl||''}))}
function createLearningQueue({preferredVideoId=null,source='goal',collectionId=null}={}){const plan=currentLearningPlan(),engine=window.EastudyLearningQueue;if(!engine)return null;return engine.create({videos:queueSourceVideos(),goalId:plan.track,preferredVideoId,source,collectionId,loop:false})}
function renderHomeGoal(){const plan=currentLearningPlan(),track=learningTrack(plan.track),pool=window.EastudyLearningQueue?.eligibleVideos(queueSourceVideos(),plan.track)||[],button=$('#homeGoalStart');if($('#homeGoalName'))$('#homeGoalName').textContent=track.name;if($('#homeGoalMeta'))$('#homeGoalMeta').textContent=pool.length?`每天 ${plan.dailyMinutes} 分钟 · ${pool.length} 条目标视频`:`每天 ${plan.dailyMinutes} 分钟 · 暂无匹配视频`;if(button){button.disabled=!pool.length;button.querySelector('span').textContent=pool.length?'开始今日学习':'暂无可学内容'}}
function renderGoalOnboarding(){const plan=currentLearningPlan(),root=$('#goalOnboardingOptions'),videos=queueSourceVideos();if(!root)return;root.innerHTML=LEARNING_TRACKS.map(track=>{const count=window.EastudyLearningQueue?.eligibleVideos(videos,track.id)?.length||0;return `<button type="button" data-onboarding-goal="${track.id}" class="${track.id===plan.track?'active':''}" ${count?'':`aria-describedby="goal-empty-${track.id}"`}><b>${track.name}</b><span>${track.focus}</span><small id="goal-empty-${track.id}">${count?`${count} 条匹配视频`:'暂时没有匹配视频'}</small></button>`}).join('');$('#goalOnboardingMinutes').value=String(plan.dailyMinutes);$('#goalOnboardingLevel').value=plan.selfLevel;$$('[data-onboarding-goal]').forEach(button=>button.onclick=()=>{$$('[data-onboarding-goal]').forEach(x=>x.classList.toggle('active',x===button))})}
function showGoalOnboarding(force=false){if(!StudentAuth.context?.user)return;const plan=currentLearningPlan();if(!force&&plan.onboardingVersion>=1)return;renderGoalOnboarding();const dialog=$('#goalOnboarding');if(dialog)dialog.hidden=false;document.body.classList.add('goal-onboarding-open')}
