function formatPlanDuration(seconds){const total=Math.max(0,Math.round(seconds));return total%60===0?`${total/60} 分钟`:`${Math.floor(total/60)}:${String(total%60).padStart(2,'0')}`}
function renderLearningPlan(){const select=$('#learningTrackSelect'),minutes=$('#dailyMinutesSelect'),saved=currentLearningPlan(),track=learningTrack(saved.track),daily=saved.dailyMinutes;if(select){select.innerHTML=LEARNING_TRACKS.map(x=>`<option value="${x.id}">${x.name}</option>`).join('');select.value=track.id}if(minutes)minutes.value=String(daily);const specific=window.EastudyLearningQueue?.eligibleVideos(queueSourceVideos(),track.id)||[],ready=specific.length>0,todayMinutes=Math.floor(studySummary().todaySeconds/60),percent=Math.min(100,Math.round(todayMinutes/daily*100));if($('#learningPlanGoalName'))$('#learningPlanGoalName').textContent=track.name;if($('#learningPlanGoalMeta'))$('#learningPlanGoalMeta').textContent=`每天 ${daily} 分钟`;if($('#learningPlanAvailability'))$('#learningPlanAvailability').textContent=ready?`已匹配 ${specific.length} 条可学习视频`:'当前目标暂无匹配视频';if($('#learningPlanProgressText'))$('#learningPlanProgressText').textContent=`${todayMinutes} / ${daily} 分钟`;const progress=$('#learningPlanProgress');if(progress){progress.setAttribute('aria-valuenow',String(percent));progress.querySelector('i').style.width=percent+'%'}const action=$('#learningPlanAction');if(action){action.disabled=!ready;action.textContent=ready?'继续学习':'暂无内容'}}
async function saveLearningPlanFromControls(){const track=$('#learningTrackSelect')?.value||'general',dailyMinutes=Number($('#dailyMinutesSelect')?.value)||20,button=$('#learningPlanSave'),status=$('#learningPlanSaveStatus');if(button){button.disabled=true;button.textContent='保存中…'}if(status){status.textContent='';status.dataset.kind=''}const result=await persistLearningPlan({track,dailyMinutes});if(button){button.disabled=false;button.textContent='确认保存'}if(result?.error){if(status){status.textContent='云端暂未同步，请检查网络后重试';status.dataset.kind='error'}return}const editor=$('#learningPlanEditor'),edit=$('#learningPlanEdit');if(editor)editor.hidden=true;if(edit){edit.setAttribute('aria-expanded','false');edit.textContent='修改'}renderLearningPlan()}
function bootLearning(){renderLearningPlan();const summary=studySummary(),days=summary.days,started=startedVideos(),completed=started.filter(row=>row.progress.completed).length,mastered=combinedVocab().filter(v=>v.state==='mastered').length,weekSeconds=days.reduce((n,day)=>n+day.seconds,0),goalMinutes=currentLearningPlan().dailyMinutes,weekGoal=goalMinutes*7,weekMinutes=Math.floor(weekSeconds/60),todayMinutes=Math.floor(summary.todaySeconds/60),goalPercent=Math.min(100,Math.round(summary.todaySeconds/(goalMinutes*60)*100)),average=started.length?Math.round(started.reduce((n,row)=>n+(Number(row.progress.watchCoveragePercent)||0),0)/started.length):0,pending=window.EastudyData?.pendingStudyEvents?.()||0,last=started[0];$('#learningChart').innerHTML=days.map(day=>`<div class="chart-bar"><b>${day.seconds&&day.seconds<60?'&lt;1m':day.mins+'m'}</b><i style="height:${day.seconds?Math.max(12,Math.min(150,day.seconds/2400*150)):2}px"></i></div>`).join('');if($('#learningTotalTime'))$('#learningTotalTime').textContent=formatStudyDuration(summary.totalSeconds);if($('#learningWeekTime'))$('#learningWeekTime').textContent=`本周 ${weekMinutes} 分钟`;if($('#learningTodayTime'))$('#learningTodayTime').textContent=summary.todaySeconds>0&&summary.todaySeconds<60?Math.round(summary.todaySeconds):todayMinutes;if($('#learningTodayUnit'))$('#learningTodayUnit').innerHTML=summary.todaySeconds>0&&summary.todaySeconds<60?'秒<br>今日已学':'分钟<br>今日已学';if($('#learningWeekGoal'))$('#learningWeekGoal').textContent=`本周目标 ${weekGoal} 分钟`;if($('#learningWeekProgress'))$('#learningWeekProgress').textContent=`${weekMinutes} / ${weekGoal}`;if($('#learningWeekProgressBar'))$('#learningWeekProgressBar').style.width=Math.min(100,Math.round(weekMinutes/weekGoal*100))+'%';if($('#learningWordCount'))$('#learningWordCount').textContent=mastered;if($('#learningStreakCount'))$('#learningStreakCount').textContent=summary.streak+' 天';if($('#learningVideoCount'))$('#learningVideoCount').textContent=started.length;if($('#learningVideoCompletion'))$('#learningVideoCompletion').textContent=`完成 ${completed} 条 · 平均覆盖 ${average}%`;if($('#learningGoalPercent'))$('#learningGoalPercent').textContent=goalPercent+'%';if($('#learningGoalRing'))$('#learningGoalRing').style.strokeDashoffset=String(302-Math.round(302*goalPercent/100));if($('#learningGoalRemaining'))$('#learningGoalRemaining').textContent=goalPercent>=100?'今天的目标已经完成':summary.todaySeconds?`还差 ${Math.max(0,goalMinutes-todayMinutes)} 分钟`:'尚未开始';if($('#learningSyncStatus'))$('#learningSyncStatus').textContent=pending?`还有 ${pending} 条学习记录待同步`:'云端数据已同步';const nextRoute=last?'/video/'+last.video.id:'/videos';['learningContinueButton','learningGoalAction'].forEach(id=>{const el=$('#'+id);if(el){el.dataset.route=nextRoute;el.textContent=last?'继续学习':'开始学习'}});const selectedDate=State.query.get('date'),view=State.query.get('view');if($('#learningWelcomeCopy'))$('#learningWelcomeCopy').textContent=selectedDate?`${selectedDate}：${formatStudyDuration(Number(summary.sessions[selectedDate])||0)}，点击下方记录可继续学习。`:view==='calendar'?'以下数据按当前账号和设备时区汇总。':goalPercent>=100?'今天的学习目标已经完成。':`今天再学 ${Math.max(0,goalMinutes-todayMinutes)} 分钟即可完成目标。`;const qs=reviewQueue().slice(0,4);$('#reviewQueue').innerHTML=qs.length?qs.map(x=>`<div class="review-word"><b>${x.word}</b><span>${x.meaning}</span><button data-review-queue="${x.word}">复习</button></div>`).join(''):'<div class="empty-state compact"><p>暂无待复习词汇。</p></div>';const recent=started.slice(0,3);$('#recentLearning').innerHTML=recent.length?recent.map(x=>`<div class="recent-row" data-video="${x.video.id}"><img src="${escapeHtml(videoCover(x.video))}" alt="${escapeHtml(displayVideoTitle(x.video))}"><div><b>${escapeHtml(displayVideoTitle(x.video))}</b><span>${Math.round(x.progress.percent||0)}% · ${escapeHtml(x.video.creator||'Eastudy')}</span></div><i data-icon="chevron-right"></i></div>`).join(''):'<div class="empty-state compact"><p>开始播放后，这里会显示当前账号的真实学习记录。</p></div>';$$('#reviewQueue [data-review-queue]').forEach(x=>x.onclick=()=>{route('/vocabulary?state=review');setTimeout(()=>openVocabReview(x.dataset.reviewQueue),80)});$$('#recentLearning [data-video]').forEach(x=>x.onclick=()=>route('/video/'+x.dataset.video));bindCards();hydrateIcons($('#learningPage'))}
