const uiMutationObserver=new MutationObserver(ms=>{if(State.lang!=='en')return;ms.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType===1)translateInterface(n);else if(n.nodeType===3&&n.parentElement)translateInterface(n.parentElement)}))});
uiMutationObserver.observe(document.body,{childList:true,subtree:true});


function activeVideoId(){const m=(State.route||'').match(/^\/video\/(\d+)/);return m?Number(m[1]):Number(State.currentVideo?.id||HOME_VIDEOS_DATA[0]?.id||0)}
async function hydrateCloudContent(){if(window.ZoContent?.localOnly)return;const cloud=window.EastudyCloudContent;if(!cloud||!window.ZoContent)return;const remote=await cloud.pullPublished();if(remote.error){State.catalogError=true;console.warn('Eastudy cloud content unavailable',remote.error);return}State.catalogError=false;if(remote.snapshot){window.ZoContent.importSnapshot(remote.snapshot,{type:'cloud.import',revision:remote.revision});window.__eastudyCloudContentLoaded=true;hydrateManagedContent()}}
function renderEmptyHome(){
 const empty=!HOME_VIDEOS_DATA.length,card=$('#priorityResumeCard'),primary=$('#todayPrimaryAction');
 if(card)card.hidden=empty;
 if(primary){primary.disabled=empty;if(empty){delete primary.dataset.route;primary.textContent='暂无已发布视频'}}
 document.querySelectorAll('.home-start,.progress-launcher').forEach(button=>{button.disabled=empty;if(empty){button.dataset.route='/videos';button.setAttribute('aria-disabled','true')}else button.removeAttribute('aria-disabled')});
 return empty;
}
function showRemovedVideo(){
 stopAllMedia('content-removed',{saveProgress:false,closeOverlays:true});
 State.mediaPlayer?.destroy();State.mediaPlayer=null;State.currentVideo=null;State.playing=false;DATA.sentences=[];
 const video=$('#video');if(video){video.pause();video.removeAttribute('src');video.querySelectorAll('source').forEach(source=>source.remove());video.load()}
 renderTranscript();$('#currentEn').textContent='该视频已移除或尚未发布';$('#currentZh').textContent='请返回视频库选择其他课程。';
 const box=$('#mediaState');if(box){box.hidden=false;box.dataset.kind='removed';$('#mediaStateTitle').textContent='该视频已移除或尚未发布';$('#mediaStateCopy').textContent='请返回视频库选择其他课程。';$('#mediaRetry').hidden=true}
  document.querySelectorAll('.practice-mode').forEach(button=>button.disabled=true);
}
function refreshManagedViews(){
 hydrateManagedContent();
 if(State.route.startsWith('/video/')){
   const available=window.ZoContent?.getVideo?.(activeVideoId())?.status==='PUBLISHED';
   if(!available)showRemovedVideo();
   else{PlaybackCountdown?.cancel('content-changed');State.nextQueueResult=null;void bootVideo()}
 }else routeNow();
}
window.addEventListener('zospeak:content-changed',refreshManagedViews);
window.addEventListener('storage',event=>{if(event.key===window.ZoContent?.KEY||event.key===null)refreshManagedViews()});
function hydrateManagedContent(){
  if(!window.ZoContent)return;
  try{
    const published=window.ZoContent.listVideos({publishedOnly:true});
    {
      const normalized=published.map(v=>({id:Number(v.id),title:v.title,titleZh:v.titleZh||'',description:v.description||'',creatorId:v.creatorId||'',creator:v.creator||'Eastudy',duration:Number(v.duration)||0,level:v.level||'A2',cover:v.cover||'assets/images/home_video_1.png',mediaUrl:v.mediaUrl||'',date:(v.publishedAt||v.updatedAt||'').slice(0,10),publishedAt:v.publishedAt||null,category:window.EastudyCatalog?.categoryLabel(v)||v.category||'待分类',topicIds:v.topicIds||[],tagIds:v.tagIds||[],tagAssignments:v.tagAssignments||[],collectionIds:v.collectionIds||[],goalIds:v.goalIds||[],goalMappings:v.goalMappings||[],status:v.status}));
      DATA.videos.splice(0,DATA.videos.length,...normalized);
      const studentVideos=published.map(v=>({id:Number(v.id),title:v.title,titleZh:v.titleZh||'',description:v.description||'',creatorId:v.creatorId||'',creator:v.creator||'Eastudy',level:v.level||'A2',duration:Number(v.duration)||0,cover:v.cover||'assets/images/home_video_1.png',mediaUrl:v.mediaUrl||'',category:window.EastudyCatalog?.categoryLabel(v)||v.category||'待分类',topicIds:v.topicIds||[],tagIds:v.tagIds||[],tagAssignments:v.tagAssignments||[],publishedAt:v.publishedAt||null,collectionIds:v.collectionIds||[],goalIds:v.goalIds||[],goalMappings:v.goalMappings||[],status:v.status}));
      HOME_VIDEOS_DATA.splice(0,HOME_VIDEOS_DATA.length,...studentVideos);
    }
    const cols=window.ZoContent.listCollections?.()||[];
    {const studentCollections=cols.filter(x=>x.status==='PUBLISHED').map(c=>({id:Number(c.id),title:c.title,subtitle:c.subtitle||'',description:c.description||'',count:(window.EastudyCatalog?.collectionMembers(published,c.id)||[]).length,cover:c.cover||'assets/images/home_collection_1.png',category:c.topicId?window.EastudyCatalog?.TOPIC_CATEGORIES[c.topicId]||'待分类':c.category||'待分类',topicId:c.topicId||'',level:c.level||''}));HOME_COLLECTIONS_DATA.splice(0,HOME_COLLECTIONS_DATA.length,...studentCollections)}
    const creators=window.ZoContent.listCreators?.()||[];
    {const managedCreators=creators.filter(c=>c&&c.name&&!/^(null|undefined)$/i.test(String(c.name).trim())).map(c=>{const videos=published.filter(v=>String(v.creatorId||'')===String(c.id)),category=videos.map(v=>window.EastudyCatalog?.categoryLabel(v)).find(Boolean)||c.category||'待分类';return {id:String(c.id),name:String(c.name).trim(),initial:String(c.name).trim().slice(0,1).toUpperCase(),bio:c.bio||'真实语境英语内容',category,videos:videos.length,learners:c.learners||'',avatar:c.avatar||'',featured:Boolean(c.featured),route:'/creator/'+encodeURIComponent(String(c.id)),channelUrl:c.channelUrl||''}});UI_CREATORS.splice(0,UI_CREATORS.length,...managedCreators)}
  }catch(e){console.warn('Eastudy managed content hydration skipped',e)}
}
hydrateManagedContent();
document.getElementById('video')?.addEventListener('loadedmetadata',event=>{const video=event.currentTarget,ratio=video.videoWidth>0&&video.videoHeight>0?`${video.videoWidth}/${video.videoHeight}`:'16/9';video.closest('.player')?.style.setProperty('--media-ratio',ratio);updateMobilePlayerGeometry()});
bindAccountUI();
const initialRoute=parseHashRoute();State.route=initialRoute.path;State.query=initialRoute.query;
applyTheme();applySettings();applyLanguage();bindCards();
void initStudentAuth().finally(()=>{routeNow();logEvent('app.boot','Eastudy production front-end ready')});


// Learning dashboard: make time metrics and detail rows actionable without changing storage contracts.
function bindLearningTimeDetails(){
  document.querySelectorAll('.learning-time-card,.learning-mini-stat').forEach(card=>{
    if(card.dataset.route||card.dataset.timeBound)return; card.dataset.timeBound='1'; card.setAttribute('role','link'); card.setAttribute('tabindex','0');
    const go=()=>route('/learning'); card.addEventListener('click',go); card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}});
  });
  document.querySelectorAll('.learning-detail-table .detail-row:not(.detail-head)').forEach(row=>{
    if(row.dataset.detailBound)return; row.dataset.detailBound='1'; row.setAttribute('role','link'); row.setAttribute('tabindex','0');
    const title=row.querySelector('b')?.textContent||''; const go=()=>{const next=startedVideos()[0]?.video?.id||HOME_VIDEOS_DATA[0]?.id;if(next)route('/video/'+next);else route('/videos');toast(next?`已打开：${title}`:'请先选择一个已发布视频')}; row.addEventListener('click',go); row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}});
  });
}
const learningObserver=new MutationObserver(()=>{if(document.getElementById('learningPage')?.classList.contains('active'))bindLearningTimeDetails()});
learningObserver.observe(document.body,{subtree:true,attributes:true,attributeFilter:['class']});
setTimeout(bindLearningTimeDetails,100);
window.addEventListener('eastudy:learning-hydrated',()=>{State.settings={...DEFAULT_SETTINGS,...Storage.get('settings',{})};applySettings();refreshStats();if(State.route==='/home'){renderHomeCreators();renderHomeHomeSections();renderMobileHome()}if(State.route==='/favorites')renderFavorites($('.favorites-tabs .active')?.dataset.favTab||'videos');if(State.route.startsWith('/compilation/'))bootCollection();if(State.route.startsWith('/creator/'))bootCreatorDetail()});

